import{_ as t,C as o,o as r,c as i,E as n,a2 as s}from"./chunks/framework.Cm6XCzck.js";const _=JSON.parse('{"title":"令牌预算，不是工作记忆的证据","description":"","frontmatter":{"title":"令牌预算，不是工作记忆的证据","date":"2026-09-02","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"长期运行的数字员工应如何证明其工作记忆有效，而不是只证明没有超过令牌预算？","summary":"一项对 55 条编程智能体轨迹的研究把工作记忆拆成存储状态、实际送达的上下文、管理工作与任务过程结果四层。这个划分揭示：相同预算不代表相同可用信息，最终成功也不能替代记忆路径的证据。","sources":["research/analysis/Q-20260902-01-working-memory-four-layer-evaluation.md"],"item_id":"Q-20260902-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-09-02-token-budget-is-not-working-memory-evidence-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-09-02-token-budget-is-not-working-memory-evidence.md","filePath":"zh/digital-employee/2026-09-02-token-budget-is-not-working-memory-evidence.md","lastUpdated":1788361073000}'),l={name:"zh/digital-employee/2026-09-02-token-budget-is-not-working-memory-evidence.md"};function p(d,e,c,m,h,u){const a=o("ArticleCover");return r(),i("div",null,[n(a,{image:"/assets/covers/daily-2026-09-02-token-budget-is-not-working-memory-evidence-cover.png",kicker:"数字员工 · 每日研究",title:"令牌预算，不是工作记忆的证据",summary:"一项对 55 条编程智能体轨迹的研究把工作记忆拆成存储状态、实际送达的上下文、管理工作与任务过程结果四层。这个划分揭示：相同预算不代表相同可用信息，最终成功也不能替代记忆路径的证据。",version:"Q-20260902-01",status:"Daily Runtime V5 · 2026-09-02",languageHref:"/en/digital-employee/2026-09-02-token-budget-is-not-working-memory-evidence",languageLabel:"English"}),e[0]||(e[0]=s('<h1 id="令牌预算-不是工作记忆的证据" tabindex="-1">令牌预算，不是工作记忆的证据 <a class="header-anchor" href="#令牌预算-不是工作记忆的证据" aria-label="Permalink to &quot;令牌预算，不是工作记忆的证据&quot;">​</a></h1><p>两个数字员工都没有超过相同的上下文容量。一个在执行前拿到了关键约束，另一个只保留了大量相关却无用的历史；前者几乎没有额外整理成本，后者反复压缩、检索和重写。若仪表盘只显示“令牌未超限”和“任务已完成”，两次运行看起来可能同样健康。</p><p>问题不在于预算没有价值，而在于它回答的是容量问题。它没有说明保存了什么、真正送达了什么、为此付出了多少管理成本，也没有说明一次成功是否掩盖了陈旧或缺失的记忆。</p><p>一项分析 55 条编程智能体轨迹的一手研究，把工作记忆评估拆成四层：存储状态、实际送达的上下文、记忆管理工作，以及任务与过程结果。研究报告显示，不同语义类型的记忆对象具有不同的保留与压缩行为；相同名义预算可能对应不同的送达内容和管理成本；某些校准收益也没有迁移到保留任务上。</p><p>由此可以得到一个有边界的治理判断：<strong>长期运行的数字员工需要分层、按发生绑定的记忆证据；容量与最终结果不能替代这四层证据。</strong></p><h2 id="同样的预算-送达的信息可能完全不同" tabindex="-1">同样的预算，送达的信息可能完全不同 <a class="header-anchor" href="#同样的预算-送达的信息可能完全不同" aria-label="Permalink to &quot;同样的预算，送达的信息可能完全不同&quot;">​</a></h2><p>上下文窗口或令牌上限描述系统最多可以承载多少内容，却不描述某个执行时刻究竟获得了哪些内容。存储中存在一条约束，也不代表检索和组装过程把它送到了需要它的那次执行。</p><p>这一区别使“记忆是否存在”和“记忆是否可用”成为两项不同的主张。前者需要存储记录，后者需要与具体执行发生绑定的送达记录。若只保存总量，系统就无法解释一次错误究竟源于没有存储、检索失败、压缩丢失，还是选择策略把正确内容排除在外。</p><p>研究还提醒我们，两个运行即使送达了相近信息，也可能支付不同的管理成本。反复检索、摘要和压缩会消耗时间与令牌；把这些工作隐藏在最终提示长度之后，会把效率结论建立在不完整的分母上。</p><h2 id="四层证据支持四类不同主张" tabindex="-1">四层证据支持四类不同主张 <a class="header-anchor" href="#四层证据支持四类不同主张" aria-label="Permalink to &quot;四层证据支持四类不同主张&quot;">​</a></h2><p>存储状态说明某一时点持久保存了什么。实际送达的上下文说明某次执行真正可见什么。管理工作说明检索、筛选、压缩和重写花费了多少资源。任务与过程结果则说明工作是否完成、过程是否满足约束。</p><p>四层不是为了制造更多指标，而是防止证据越权。不能用“存储中有”证明“执行时看见了”，不能用“提示很短”证明“管理成本很低”，也不能用“任务完成”证明记忆路径正确。</p><p>因此，审计记录至少需要保留记忆对象身份与类型、转换它的策略版本、保留表示、执行时送达的表示、管理成本，以及对应的过程结果。系统可以出于隐私和规模原因保存摘要或哈希，但必须明确哪一层被摘要、丢失了什么，以及还能支持哪些主张。</p><h2 id="策略更新不能继承旧版本的资格" tabindex="-1">策略更新不能继承旧版本的资格 <a class="header-anchor" href="#策略更新不能继承旧版本的资格" aria-label="Permalink to &quot;策略更新不能继承旧版本的资格&quot;">​</a></h2><p>研究报告的另一个负面结果是，部分校准收益没有迁移到保留任务。这并不证明某种记忆策略普遍失败，却足以反对一种常见做法：新策略只因源自旧策略，就自动继承旧版本的资格。</p><p>自适应记忆会改变保留、压缩和检索规则，也可能改变送达内容与管理成本。每次变更都应产生新的策略身份，并把验证证据绑定到该版本及其实际评估分布。任务类型、工具集合、信息敏感度或工作时长发生明显变化时，先前校准不应静默授权新分布上的激活。</p><p>这与普通配置更新不同。记忆策略决定未来执行能够看到什么，因此它影响推理前提，也影响恢复时能否重建原有上下文。</p><h2 id="最终成功不能替代过程证据" tabindex="-1">最终成功不能替代过程证据 <a class="header-anchor" href="#最终成功不能替代过程证据" aria-label="Permalink to &quot;最终成功不能替代过程证据&quot;">​</a></h2><p>一个任务可以在缺少关键信息时侥幸完成，也可能依靠大量隐藏的整理工作获得正确结果。相反，一次失败也未必由记忆造成。只看最终结果，会把原因不同的路径压成同一个标签。</p><p>更可靠的做法是分别判断：存储是否符合声明；执行是否获得所需上下文；管理成本是否在约束内；过程和结果是否满足任务要求。只有在这些主张都需要成立时，才要求相应证据同时存在。</p><p>这种分账也改善恢复。发生中断后，系统不仅要知道“从哪个任务继续”，还要知道中断发生时使用了哪个记忆策略、哪些内容已经送达，以及恢复运行是否仍处在同一证据边界内。</p><h2 id="证据边界仍然很窄" tabindex="-1">证据边界仍然很窄 <a class="header-anchor" href="#证据边界仍然很窄" aria-label="Permalink to &quot;证据边界仍然很窄&quot;">​</a></h2><p>现有实证来自编程智能体轨迹，不是任意企业数字员工。它没有证明身份安全、调用授权、持久化可靠性、外部效果幂等或不可逆行动安全，也没有确定一个跨工作负载最优的记忆策略。</p><p>它支持的结论更具体：工作记忆评估不能缩减为名义容量或最终成功；当策略改变时，资格需要绑定新版本、实际送达和适用分布重新建立。</p><p>接下来真正困难的问题是：怎样在不长期保存敏感全文的情况下证明送达事实；数千次执行中应如何抽样；哪些分布变化必须触发重新验证；以及记忆策略回滚怎样与外部任务效果的恢复分开处理。</p><p><strong>一手来源：</strong> <a href="https://arxiv.org/abs/2608.31057" target="_blank" rel="noreferrer">工作记忆评估研究</a></p>',26))])}const k=t(l,[["render",p]]);export{_ as __pageData,k as default};
